package org.jsoup;

import java.io.*;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.net.URL;
import java.util.*;
import org.jsoup.helper.DataUtil;
import org.jsoup.helper.HttpConnection;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Parser;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Whitelist;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Jsoup_isValid_TriageGen2Test {

    @Test
    public void testIsValid_WithValidHtml() {
        String html = "<p>Valid HTML</p>";
        Whitelist whitelist = Whitelist.basicWithImages();
        Assert.assertTrue(Jsoup.isValid(html, whitelist));
    }

    @Test
    public void testIsValid_WithInvalidHtml() {
        String html = "<script>alert('Invalid HTML');</script>";
        Whitelist whitelist = Whitelist.basicWithImages();
        Assert.assertFalse(Jsoup.isValid(html, whitelist));
    }

    @Test
    public void testIsValid_WithEmptyHtml() {
        String html = "";
        Whitelist whitelist = Whitelist.basicWithImages();
        Assert.assertTrue(Jsoup.isValid(html, whitelist));
    }

    @Test
    public void testIsValid_WithOnlyWhitespace() {
        String html = "   ";
        Whitelist whitelist = Whitelist.basicWithImages();
        Assert.assertTrue(Jsoup.isValid(html, whitelist));
    }

    @Test
    public void testIsValid_WithImageTag() {
        String html = "<img src='image.jpg'>";
        Whitelist whitelist = Whitelist.simpleText();
        Assert.assertFalse(Jsoup.isValid(html, whitelist));
    }

    @Test
    public void testIsValid_WithSimpleText() {
        String html = "Simple text";
        Whitelist whitelist = Whitelist.simpleText();
        Assert.assertTrue(Jsoup.isValid(html, whitelist));
    }

    @Test
    public void testIsValid_WithAnchorTag() {
        String html = "<a href='http://example.com'>Link</a>";
        Whitelist whitelist = Whitelist.simpleText();
        Assert.assertFalse(Jsoup.isValid(html, whitelist));
    }

    @Test
    public void testIsValid_WithListTag() {
        String html = "<ul><li>Item</li></ul>";
        Whitelist whitelist = Whitelist.simpleText();
        Assert.assertFalse(Jsoup.isValid(html, whitelist));
    }

    @Test
    public void testIsValid_WithValidAnchorInBasicWhitelist() {
        String html = "<a href='http://example.com'>Link</a>";
        Whitelist whitelist = Whitelist.basicWithImages();
        Assert.assertTrue(Jsoup.isValid(html, whitelist));
    }

    @Test
    public void testIsValid_WithCustomWhitelist() {
        Whitelist customWhitelist = new Whitelist();
        customWhitelist.addTags("customTag");
        String html = "<customTag>Custom Content</customTag>";
        Assert.assertTrue(Jsoup.isValid(html, customWhitelist));
    }

    @Test
    public void testIsValid_WithInvalidCustomTag() {
        Whitelist customWhitelist = new Whitelist();
        String html = "<customTag>Invalid Content</customTag>";
        Assert.assertFalse(Jsoup.isValid(html, customWhitelist));
    }
}
